 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelMulSigmoidMulAddCustom {
public:
    __aicore__ inline KernelMulSigmoidMulAddCustom() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output,
                                GM_ADDR mulscalar1, GM_ADDR mulscalar2, GM_ADDR mulscalar3,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, formerLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, tailLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        // Read scalar values from GM (1-element tensors)
        __gm__ T *ms1Ptr = (__gm__ T *)mulscalar1;
        __gm__ T *ms2Ptr = (__gm__ T *)mulscalar2;
        __gm__ T *ms3Ptr = (__gm__ T *)mulscalar3;
        this->mulscalar1_val = ms1Ptr[0];
        this->mulscalar2_val = ms2Ptr[0];
        this->mulscalar3_val = ms3Ptr[0];

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) == sizeof(half)) {
            // FP16 needs extra FP32 buffers for upcast computation
            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
        } else {
            // FP32 needs one temp buffer
            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{
            1,
            static_cast<uint32_t>(curTileLength * sizeof(T)),
            0, 0, 0
        };
        AscendC::DataCopyPad(xLocal, inputGm[progress * this->tileLength], copyParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 path: direct computation
            AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
            AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
            AscendC::LocalTensor<float> tempLocal = tmpBuf1.Get<float>();

            // Step 1: input * mulscalar1
            AscendC::Muls(tempLocal, xLocal, this->mulscalar1_val, curTileLength);

            // Step 2: sigmoid(tempLocal)
            AscendC::Sigmoid(yLocal, tempLocal, curTileLength);

            // Step 3: sigmoid_res * mulscalar2
            AscendC::Muls(tempLocal, yLocal, this->mulscalar2_val, curTileLength);

            // Step 4: mul2_res + mulscalar3
            AscendC::Adds(yLocal, tempLocal, this->mulscalar3_val, curTileLength);

            inQueueX.FreeTensor(xLocal);
            outQueueY.EnQue<float>(yLocal);
        } else {
            // FP16 path: upcast to FP32, compute, downcast back
            AscendC::LocalTensor<half> xLocalFp16 = inQueueX.DeQue<half>();
            AscendC::LocalTensor<half> yLocalFp16 = outQueueY.AllocTensor<half>();

            AscendC::LocalTensor<float> xLocalFp32 = tmpBuf1.Get<float>();
            AscendC::LocalTensor<float> mid1LocalFp32 = tmpBuf2.Get<float>();
            AscendC::LocalTensor<float> mid2LocalFp32 = tmpBuf3.Get<float>();
            AscendC::LocalTensor<float> outLocalFp32 = tmpBuf4.Get<float>();

            // Cast fp16 -> fp32
            AscendC::Cast(xLocalFp32, xLocalFp16, AscendC::RoundMode::CAST_NONE, curTileLength);

            // Step 1: input * mulscalar1 (FP32)
            AscendC::Muls(mid1LocalFp32, xLocalFp32, (float)this->mulscalar1_val, curTileLength);

            // Step 2: sigmoid(mid1) (FP32)
            AscendC::Sigmoid(mid2LocalFp32, mid1LocalFp32, curTileLength);

            // Step 3: sigmoid_res * mulscalar2 (FP32)
            AscendC::Muls(mid1LocalFp32, mid2LocalFp32, (float)this->mulscalar2_val, curTileLength);

            // Step 4: mul2_res + mulscalar3 (FP32)
            AscendC::Adds(outLocalFp32, mid1LocalFp32, (float)this->mulscalar3_val, curTileLength);

            // Cast fp32 -> fp16
            AscendC::Cast(yLocalFp16, outLocalFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);

            inQueueX.FreeTensor(xLocalFp16);
            outQueueY.EnQue<half>(yLocalFp16);
        }
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{
            1,
            static_cast<uint32_t>(curTileLength * sizeof(T)),
            0, 0, 0
        };
        AscendC::DataCopyPad(outputGm[progress * this->tileLength], yLocal, copyParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf4;
    AscendC::GlobalTensor<T> inputGm;
    AscendC::GlobalTensor<T> outputGm;
    int64_t blockLength;
    int64_t tileLength;
    T mulscalar1_val;
    T mulscalar2_val;
    T mulscalar3_val;
};

extern "C" __global__ __aicore__ void MulSigmoidMulAddCustom(GM_ADDR input, GM_ADDR output,
                                                               GM_ADDR mulscalar1, GM_ADDR mulscalar2, GM_ADDR mulscalar3,
                                                               int64_t formerNum, int64_t formerLength,
                                                               int64_t tailLength, int64_t tileLength,
                                                               int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelMulSigmoidMulAddCustom<half> op;
        op.Init(input, output, mulscalar1, mulscalar2, mulscalar3,
                formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelMulSigmoidMulAddCustom<float> op;
        op.Init(input, output, mulscalar1, mulscalar2, mulscalar3,
                formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
