#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_MulSigmoidMulAddCustom.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor MulSigmoidMulAddCustom(const at::Tensor &input,
                                   const at::Tensor &mulscalar1,
                                   const at::Tensor &mulscalar2,
                                   const at::Tensor &mulscalar3)
{
    // ---- 输入校验 ----
    TORCH_CHECK(input.scalar_type() == at::kHalf || input.scalar_type() == at::kFloat,
                "MulSigmoidMulAddCustom: only float16 and float32 are supported, got ", input.scalar_type());
    TORCH_CHECK(mulscalar1.scalar_type() == input.scalar_type(),
                "MulSigmoidMulAddCustom: mulscalar1 dtype must match input dtype");
    TORCH_CHECK(mulscalar2.scalar_type() == input.scalar_type(),
                "MulSigmoidMulAddCustom: mulscalar2 dtype must match input dtype");
    TORCH_CHECK(mulscalar3.scalar_type() == input.scalar_type(),
                "MulSigmoidMulAddCustom: mulscalar3 dtype must match input dtype");
    TORCH_CHECK(input.is_contiguous(), "MulSigmoidMulAddCustom: input must be contiguous");

    at::Tensor output = at::empty_like(input);

    int64_t totalLength = input.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = input.element_size();

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    // bufferCoefficient from UB allocation table in design.md:
    // float32: 20 (inQueueX * 2 + outQueueY * 2 + tempBuf * 1 = 8 + 8 + 4 = 20)
    // float16: 20 (inQueueX * 2 + outQueueY * 2 + 4 tempBufs * 4 = 4 + 4 + 16 = 24)
    // Actually for this kernel:
    //   float32: inQueueX(2*4) + outQueueY(2*4) + tmpBuf1(1*4) = 8 + 8 + 4 = 20
    //   float16: inQueueX(2*2) + outQueueY(2*2) + tmpBuf1(1*4) + tmpBuf2(1*4) + tmpBuf3(1*4) + tmpBuf4(1*4) = 4 + 4 + 4 + 4 + 4 + 4 = 24
    int64_t bufferCoefficient;
    if (dtypeSize == 4) {
        bufferCoefficient = 20;
    } else {
        bufferCoefficient = 24;
    }

    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // All parameters must be left values for EXEC_KERNEL_CMD
    int64_t formerNumLval = formerNum;
    int64_t formerLengthLval = formerLength;
    int64_t tailLengthLval = tailLength;
    int64_t tileLengthLval = tileLength;
    int64_t dtypeSizeLval = dtypeSize;

    EXEC_KERNEL_CMD(MulSigmoidMulAddCustom, blockDim,
                    input, output,
                    mulscalar1, mulscalar2, mulscalar3,
                    formerNumLval, formerLengthLval, tailLengthLval, tileLengthLval, dtypeSizeLval);

    return output;
}

}  // namespace ascend_kernel
