class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, input: torch.Tensor, mulscalar1: torch.Tensor,
                mulscalar2: torch.Tensor, mulscalar3: torch.Tensor) -> torch.Tensor:
        # 输入校验
        assert input.dtype in (torch.float16, torch.float32)
        assert input.is_contiguous()
        assert mulscalar1.dtype == input.dtype
        assert mulscalar2.dtype == input.dtype
        assert mulscalar3.dtype == input.dtype

        # 调用注册的 AscendC 算子
        return torch.ops.npu.MulSigmoidMulAddCustom(input, mulscalar1, mulscalar2, mulscalar3)
