13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelMulSigmoidMulAddCustom {
17	public:
18	    __aicore__ inline KernelMulSigmoidMulAddCustom() {}
19	
20	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output,
21	                                GM_ADDR mulscalar1, GM_ADDR mulscalar2, GM_ADDR mulscalar3,
22	                                int64_t formerNum, int64_t formerLength,
23	                                int64_t tailLength, int64_t tileLength)
24	    {
25	        int64_t blockIdx = AscendC::GetBlockIdx();
26	
27	        if (blockIdx < formerNum) {
28	            this->blockLength = formerLength;
29	            int64_t offset = formerLength * blockIdx;
30	            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, formerLength);
31	            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
32	        } else {
33	            this->blockLength = tailLength;
34	            int64_t tailIdx = blockIdx - formerNum;
35	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
36	            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, tailLength);
37	            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
38	        }
39	
40	        this->tileLength = tileLength;
41	
42	        // Read scalar values from GM (1-element tensors)
43	        __gm__ T *ms1Ptr = (__gm__ T *)mulscalar1;
44	        __gm__ T *ms2Ptr = (__gm__ T *)mulscalar2;
45	        __gm__ T *ms3Ptr = (__gm__ T *)mulscalar3;
46	        this->mulscalar1_val = ms1Ptr[0];
47	        this->mulscalar2_val = ms2Ptr[0];
48	        this->mulscalar3_val = ms3Ptr[0];
49	
50	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
51	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
52	
53	        if constexpr (sizeof(T) == sizeof(half)) {
54	            // FP16 needs extra FP32 buffers for upcast computation
55	            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
56	            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
57	            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
58	            pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
59	        } else {
60	            // FP32 needs one temp buffer
61	            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
62	        }
63	    }
64	
65	    __aicore__ inline void Process()
66	    {
67	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
68	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
69	
70	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
71	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
72	
73	        for (int64_t i = 0; i < tileNum - 1; ++i) {
74	            CopyIn(i, this->tileLength);
75	            Compute(i, this->tileLength);
76	            CopyOut(i, this->tileLength);
77	        }
78	        if (tileNum > 0) {
79	            CopyIn(tileNum - 1, alignedTailLen);
80	            Compute(tileNum - 1, alignedTailLen);
81	            CopyOut(tileNum - 1, alignedTailLen);
82	        }
83	    }
84	
85	private:
86	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
87	    {
88	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
89	        AscendC::DataCopyExtParams copyParams{
90	            1,
91	            static_cast<uint32_t>(curTileLength * sizeof(T)),
92	            0, 0, 0
93	        };
94	        AscendC::DataCopyPad(xLocal, inputGm[progress * this->tileLength], copyParams);
95	        inQueueX.EnQue(xLocal);
96	    }
97	
98	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
99	    {
100	        if constexpr (sizeof(T) == sizeof(float)) {
101	            // FP32 path: direct computation
102	            AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
103	            AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
104	            AscendC::LocalTensor<float> tempLocal = tmpBuf1.Get<float>();
105	
106	            // Step 1: input * mulscalar1
107	            AscendC::Muls(tempLocal, xLocal, this->mulscalar1_val, curTileLength);
108	
109	            // Step 2: sigmoid(tempLocal)
110	            AscendC::Sigmoid(yLocal, tempLocal, curTileLength);
111	
112	            // Step 3: sigmoid_res * mulscalar2
113	            AscendC::Muls(tempLocal, yLocal, this->mulscalar2_val, curTileLength);
114	
115	            // Step 4: mul2_res + mulscalar3
116	            AscendC::Adds(yLocal, tempLocal, this->mulscalar3_val, curTileLength);
117	
118	            inQueueX.FreeTensor(xLocal);
119	            outQueueY.EnQue<float>(yLocal);
120	        } else {
121	            // FP16 path: upcast to FP32, compute, downcast back
122	            AscendC::LocalTensor<half> xLocalFp16 = inQueueX.DeQue<half>();
123	            AscendC::LocalTensor<half> yLocalFp16 = outQueueY.AllocTensor<half>();
124	
125	            AscendC::LocalTensor<float> xLocalFp32 = tmpBuf1.Get<float>();
126	            AscendC::LocalTensor<float> mid1LocalFp32 = tmpBuf2.Get<float>();
127	            AscendC::LocalTensor<float> mid2LocalFp32 = tmpBuf3.Get<float>();
128	            AscendC::LocalTensor<float> outLocalFp32 = tmpBuf4.Get<float>();
129	
130	            // Cast fp16 -> fp32
131	            AscendC::Cast(xLocalFp32, xLocalFp16, AscendC::RoundMode::CAST_NONE, curTileLength);
132	
133	            // Step 1: input * mulscalar1 (FP32)
134	            AscendC::Muls(mid1LocalFp32, xLocalFp32, (float)this->mulscalar1_val, curTileLength);
135	
136	            // Step 2: sigmoid(mid1) (FP32)
137	            AscendC::Sigmoid(mid2LocalFp32, mid1LocalFp32, curTileLength);
138	
139	            // Step 3: sigmoid_res * mulscalar2 (FP32)
140	            AscendC::Muls(mid1LocalFp32, mid2LocalFp32, (float)this->mulscalar2_val, curTileLength);
141	
142	            // Step 4: mul2_res + mulscalar3 (FP32)
143	            AscendC::Adds(outLocalFp32, mid1LocalFp32, (float)this->mulscalar3_val, curTileLength);
144	
145	            // Cast fp32 -> fp16
146	            AscendC::Cast(yLocalFp16, outLocalFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
147	
148	            inQueueX.FreeTensor(xLocalFp16);
149	            outQueueY.EnQue<half>(yLocalFp16);
150	        }
151	    }
152	
153	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
154	    {
155	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
156	        AscendC::DataCopyExtParams copyParams{
157	            1,
158	            static_cast<uint32_t>(curTileLength * sizeof(T)),
159	            0, 0, 0
160	        };
161	        AscendC::DataCopyPad(outputGm[progress * this->tileLength], yLocal, copyParams);
162	        outQueueY.FreeTensor(yLocal);
163	    }
164	
165	private:
166	    AscendC::TPipe pipe;
167	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
168	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
169	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
170	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
171	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf3;
172	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf4;
173	    AscendC::GlobalTensor<T> inputGm;
174	    AscendC::GlobalTensor<T> outputGm;
175	    int64_t blockLength;
176	    int64_t tileLength;
177	    T mulscalar1_val;
178	    T mulscalar2_val;
179	    T mulscalar3_val;
180	};
181	
182	extern "C" __global__ __aicore__ void MulSigmoidMulAddCustom(GM_ADDR input, GM_ADDR output,
183	                                                               GM_ADDR mulscalar1, GM_ADDR mulscalar2, GM_ADDR mulscalar3,
184	                                                               int64_t formerNum, int64_t formerLength,
185	                                                               int64_t tailLength, int64_t tileLength,
186	                                                               int64_t dtypeSize)
187	{
188	    if (dtypeSize == 2) {
189	        KernelMulSigmoidMulAddCustom<half> op;
190	        op.Init(input, output, mulscalar1, mulscalar2, mulscalar3,
191	                formerNum, formerLength, tailLength, tileLength);
192	        op.Process();
193	    } else {
194	        KernelMulSigmoidMulAddCustom<float> op;
195	        op.Init(input, output, mulscalar1, mulscalar2, mulscalar3,
196	                formerNum, formerLength, tailLength, tileLength);
197	        op.Process();
198	    }
199	}
